// Vista previa local sin dependencias. No es necesaria en Vercel.
const http=require('node:http'),fs=require('node:fs'),path=require('node:path');
const root=__dirname,mime={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript; charset=utf-8','.json':'application/json','.webp':'image/webp','.png':'image/png','.svg':'image/svg+xml','.jpg':'image/jpeg','.pdf':'application/pdf','.mp4':'video/mp4','.webm':'video/webm','.md':'text/plain; charset=utf-8','.txt':'text/plain; charset=utf-8'};
http.createServer((req,res)=>{let name;try{name=decodeURIComponent(new URL(req.url,'http://localhost').pathname)}catch{res.writeHead(400).end();return}let file=path.resolve(root,'.'+(name==='/'?'/index.html':name));if(file!==root&&!file.startsWith(root+path.sep)){res.writeHead(403).end();return}if(!path.extname(file)&&fs.existsSync(file+'.html'))file+='.html';fs.stat(file,(err,s)=>{if(err||!s.isFile()){res.writeHead(404).end('No encontrado');return}const headers={'Content-Type':mime[path.extname(file)]||'application/octet-stream','Accept-Ranges':'bytes','Cache-Control':'no-cache'};const range=req.headers.range;if(range){const m=/^bytes=(\d+)-(\d*)$/.exec(range);if(!m){res.writeHead(416,{'Content-Range':`bytes */${s.size}`}).end();return}const start=Number(m[1]),end=m[2]?Math.min(Number(m[2]),s.size-1):s.size-1;if(start>end||start>=s.size){res.writeHead(416,{'Content-Range':`bytes */${s.size}`}).end();return}res.writeHead(206,{...headers,'Content-Length':end-start+1,'Content-Range':`bytes ${start}-${end}/${s.size}`});fs.createReadStream(file,{start,end}).pipe(res)}else{res.writeHead(200,{...headers,'Content-Length':s.size});fs.createReadStream(file).pipe(res)}})}).listen(4173,'127.0.0.1',()=>console.log('Lightship: http://127.0.0.1:4173'));
